import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;

public class AssetSearchServlet extends HttpServlet {

    private static final Pattern ALPHA_NUM = Pattern.compile("^[a-zA-Z0-9_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String limit = req.getParameter("limit");

        // Validate category against allowlist
        if (category == null || !ALPHA_NUM.matcher(category).matches()) {
            resp.sendError(400, "Invalid category");
            return;
        }

        // Validate direction
        if (direction == null) direction = "ASC";
        if (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC")) {
            direction = "ASC";
        }

        // Validate limit is numeric
        int parsedLimit = 50;
        try {
            if (limit != null) parsedLimit = Math.min(Integer.parseInt(limit), 500);
        } catch (NumberFormatException e) {
            parsedLimit = 50;
        }

        // Sort column - developer assumes frontend only sends valid columns
        // but does NOT validate sortCol against allowlist
        if (sortCol == null) sortCol = "asset_name";

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = getDataSource().getConnection();
            stmt = conn.createStatement();

            // Vulnerable: sortCol is injected directly into ORDER BY clause
            // Parameterized queries cannot be used for identifiers (column names)
            String query = "SELECT asset_id, asset_name, category, value, last_updated " +
                          "FROM assets WHERE category = '" + category + "' " +
                          "ORDER BY " + sortCol + " " + direction + " " +
                          "LIMIT " + parsedLimit;

            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\":").append(rs.getInt(1))
                   .append(",\"name\":\"").append(escapeJson(rs.getString(2)))
                   .append("\",\"category\":\"").append(escapeJson(rs.getString(3)))
                   .append("\",\"value\":").append(rs.getDouble(4))
                   .append(",\"updated\":\"").append(rs.getTimestamp(5)).append("\"}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            // Log but don't expose SQL errors to client
            getServletContext().log("Query failed", e);
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException ignored) {}
            try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private javax.sql.DataSource getDataSource() throws ServletException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/assetdb");
        } catch (javax.naming.NamingException e) {
            throw new ServletException("DataSource lookup failed", e);
        }
    }
}
